private void resetNextEpisodeState() {
    cancelCountdownTimer();
    this.creditsPromptShown = false;
    this.creditsPromptDismissed = false;
    if (this.nextEpisodeOverlay != null) {
        this.nextEpisodeOverlay.setVisibility(8);
    }
    if (this.episodeTransitionOverlay != null) {
        this.episodeTransitionOverlay.setVisibility(8);
    }
}
